describe('Modal Title Announcement', () => {
  beforeEach(() => {
    cy.visit('/modal-page');
  });

  it('should announce modal title when opened', () => {
    // Open the modal by clicking the trigger button
    cy.get('[data-testid="open-modal-button"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal title is present and announced
    cy.get('[data-testid="modal-title"]').should('contain', 'Confirm Action');

    // Verify aria-label or aria-labelledby is set for screen readers
    cy.get('[data-testid="modal-dialog"]').should('have.attr', 'aria-labelledby');

    // Verify modal has focus when opened
    cy.get('[data-testid="modal-dialog"]').should('have.focus');

    // Verify modal title is read by screen reader (using Cypress accessibility plugin)
    cy.get('[data-testid="modal-title"]').should('have.attr', 'aria-label', 'Confirm Action');
  });

  it('should handle modal with empty title gracefully', () => {
    // Open modal with empty title
    cy.get('[data-testid="open-empty-modal-button"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal title element exists but is empty
    cy.get('[data-testid="modal-title"]').should('be.visible');
    cy.get('[data-testid="modal-title"]').should('have.length', 0);

    // Verify modal still has focus and is interactive
    cy.get('[data-testid="modal-dialog"]').should('have.focus');

    // Verify modal has aria-label fallback if title is empty
    cy.get('[data-testid="modal-dialog"]').should('have.attr', 'aria-label');

    // Verify close button is accessible
    cy.get('[data-testid="close-modal-button"]').should('be.visible');
    cy.get('[data-testid="close-modal-button"]').should('have.attr', 'aria-label', 'Close modal');
  });
});
